package io.dndroll.backup;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class CampaignEvidenceRebindIT {
 @TempDir Path root;
 @Test void auditedSnapshotIsScopedDeterministicAndReadOnly()throws Exception{var owner=new RecoveryAuditIT();owner.root=root;try(var f=owner.new Fixture()){var before=f.snapshot();UUID target=UUID.randomUUID(),seed=UUID.randomUUID();var p=CampaignEvidenceRebindCommand.inspect(f.archive,f.url,f.username,f.password,f.assets,f.campaign,target,seed);assertTrue(p.consistent(),p.blockers().toString());assertEquals("BLOCKED",p.status());assertFalse(p.executable());assertEquals(p,CampaignEvidenceRebindCommand.inspect(f.archive,f.url,f.username,f.password,f.assets,f.campaign,target,seed));assertEquals(before,f.snapshot());assertFalse(p.toString().contains("PRIVATE_AUDIT"));}}
 @Test void changedRowsAndSchemaAreRejectedBeforeRebind()throws Exception{var owner=new RecoveryAuditIT();owner.root=root;try(var f=owner.new Fixture()){f.jdbc.update("update campaign set name='changed' where id=?",f.campaign);assertThrows(java.io.IOException.class,()->CampaignEvidenceRebindCommand.inspect(f.archive,f.url,f.username,f.password,f.assets,f.campaign,UUID.randomUUID(),UUID.randomUUID()));f.jdbc.execute("alter table stabilization_state add column unknown_source jsonb");assertThrows(java.io.IOException.class,()->CampaignEvidenceRebindCommand.inspect(f.archive,f.url,f.username,f.password,f.assets,f.campaign,UUID.randomUUID(),UUID.randomUUID()));}}
 @Test void existingOrMissingSourceCannotBecomeTargetAuthority()throws Exception{var owner=new RecoveryAuditIT();owner.root=root;try(var f=owner.new Fixture()){assertThrows(java.io.IOException.class,()->CampaignEvidenceRebindCommand.inspect(f.archive,f.url,f.username,f.password,f.assets,f.campaign,f.campaign,UUID.randomUUID()));assertThrows(java.io.IOException.class,()->CampaignEvidenceRebindCommand.inspect(f.archive,f.url,f.username,f.password,f.assets,UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID()));}}
}
